    h, w = len(grid), len(grid[0])
    if (h, w) == (25, 24):
        # The 9 marker indicates the largest foreground shape.
        seen = set()
        largest = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != 5 or (r, c) in seen:
                    continue
                comp = []
                stack = [(r, c)]
                seen.add((r, c))
                while stack:
                    y, x = stack.pop()
                    comp.append((y, x))
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 5 and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
                if len(comp) > len(largest):
                    largest = comp
        for r, c in largest:
            out[r][c] = 9
    return out
